{{
Relationskette/align
| (\bigwedge^2 L ) (e_2 \wedge e_3) 
|| L(e_2) \wedge L(e_3)
|| (  25 e_1 + 1 e_2 )   \wedge ( 30 e_1 - 75 e_2)
|| - 1875 e_1 \wedge e_2 + 30 e_2 \wedge  e_1  
|| -  1905 e_1 \wedge  e_2
||
|SZ=.
}}
